    let mut f: i32 = cropy;
    if q == 1 {
        f = cropy + wcpt;
    }
    if q == 2 {
        e = cropx + wcpt;
        f = cropy + hcpt;
    }
    if q == 3 {
        e = cropx + hcpt;
    }
    ev_set(views, 24, r, 17, e);
    ev_set(views, 24, r, 18, f);
